import json,re
enemies={l.split('|')[0]:l.strip().split('|') for l in open('data/enemies.dat') if not l.startswith('#')}
items={l.split('|')[0]:l.strip().split('|') for l in open('data/items.dat') if not l.startswith('#')}
zones={l.split('|')[0]:l.strip().split('|') for l in open('data/zones.dat') if not l.startswith('#')}
RATE=[100,120,145,175,210]
def calc(rec):
    lvl=rec['lvl']; luck=rec['luck']; streak=0
    gl=0; lc=luck
    for eq in rec['eq']:
        it=items[eq]
        for p in it[3].split(';'):
            m=re.match(r'([A-Z]+)\+(-?\d+)$',p)
            k,v=m.group(1),int(m.group(2))
            if k=='GLD': gl+= v*2 if it[1]=='trinket' else v
            elif k=='LCK': lc+=v
    if lc>10: lc=(lc-10)//3+10
    e=enemies[rec['enemy']]; z=zones[rec['zone']]
    el=int(e[3]); bonus=int(z[3])
    d=lvl-el
    if d>4: f=max(25,100-(d-4)*15)
    elif d>=-3: f=100
    else: f=100+min(5,-3-d)*10
    base=int(int(RATE[int(z[1])]*bonus/100)*f/100)
    tot=base+gl+2*lc+100
    if e[2]!='critter': tot+=3*min(int(rec['save'] and 0 or 0),8)
    return max(1,min(999,tot))
if __name__=='__main__':
    import sys
    r=json.load(open(sys.argv[1]))
    bad=0
    for x in r:
        got=int(x['loot'].split()[1])
        c=calc(x)
        if c!=got:
            bad+=1; print(x['enemy'],x['zone'],x['lvl'],got,c)
    print(bad,len(r))
